FT area = FT(0);
const size_t n = polygon.size();
for (size_t i = 0; i < n; ++i) {
    const Point_2& p1 = polygon[i];
    const Point_2& p2 = polygon[(i + 1) % n];
    area += (p1.x() * p2.y()) - (p2.x() * p1.y());
}
return area / FT(2);

